  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('enforces enum constraints without echoing values and passes valid extra keys through unchanged', async () => {
    const registry = new ToolRegistry();
    const received: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'convert_temp',
        description: 'Convert temperature units',
        inputSchema: {
          type: 'object',
          properties: {units: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['units'],
        },
      },
      async input => {
        received.push(input);
        return 'ok';
      }
    );

    const rejected = await registry.execute('convert_temp', {units: 'secret-kelvin'});
    const accepted = await registry.execute('convert_temp', {units: 'celsius', traceId: 't-9'});

    expect({
      mentionsFieldAndEnum: rejected.result.includes('units') && rejected.result.includes('enum'),
      leaksOffendingValue: rejected.result.includes('secret-kelvin'),
      acceptedResult: accepted.result,
      received,
    }).toEqual({
      mentionsFieldAndEnum: true,
      leaksOffendingValue: false,
      acceptedResult: 'ok',
      received: [{units: 'celsius', traceId: 't-9'}],
    });
  });

