      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const postalSchema: Record<string, unknown> = {
      type: 'object',
      properties: {postalCode: {type: 'string'}},
      required: ['postalCode'],
    };
    let activeSchema = citySchema;
    registry.register(
      () => ({name: 'locate', description: 'Locate region', inputSchema: activeSchema}),
      async input => String(input.city ?? input.postalCode)
    );

    const firstValid = await registry.execute('locate', {city: 'Dublin'});
    const cachedValid = await registry.execute('locate', {city: 'Cork'});
    activeSchema = postalSchema;
    const staleRejected = await registry.execute('locate', {city: 'Cork'});

    expect({
      firstValid: firstValid.result,
      cachedValid: cachedValid.result,
      mentionsNewField: staleRejected.result.includes('postalCode'),
    }).toEqual({
      firstValid: 'Dublin',
      cachedValid: 'Cork',
      mentionsNewField: true,
    });
  });
});

